comms.text:
@1 וְאַתְּ תְּפַקֵד יָת בְּנֵי יִשְׂרָאֵל וְיִסְבוּן לָךְ מִשְׁחָא זֵיתָא דַכְיָא כָּתִישָׁא לְאַנְהָרָא לְאַדְלָקָא בוֹצִינַיָא תְּדִירָא:
@2 בְּמַשְׁכַּן זִמְנָא מִבָּרָא לְפָרֻכְתָּא דְעַל סַהֲדוּתָא יְסַדַר יָתֵהּ אַהֲרֹן וּבְנוֹהִי מֵרַמְשָׁא עַד צַפְרָא קָדָם יְיָ קְיָם עֲלָם לְדָרֵיהוֹן מִן בְּנֵי יִשְׂרָאֵל:וְ
@3 אַתְּ קָרֵב לְוָתָךְ יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ מִגוֹ בְּנֵי יִשְׂרָאֵל לְשַׁמָשָׁא קֳדָמַי אַהֲרֹן נָדָב וַאֲבִיהוּא אֶלְעָזָר וְאִיתָמָר בְּנֵי אַהֲרֹן:
@4 וְתַעְבֵּד לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ לִיקָר וּלְתֻשְׁבְּחָן:
@5 וְאַתְּ תְּמַלֵל עִם כָּל חַכִּימֵי לִבָּא דְאַשְׁלֵמִית עִמֵהּ רוּחַ חָכְמְתָא וְיַעְבְּדוּן יָת לְבוּשֵׁי אַהֲרֹן לְקַדָשׁוּתֵהּ לְשַׁמָשָׁא קֳדָמַי:
@6 וְאִלֵין לְבוּשַׁיָא דִי יַעְבְּדוּן חוּשְׁנָא וְאֵפוֹדָא וּמְעִילָא וְכִתּוּנָא מְרַמְצָא מִצְנֶפְתָּא וְהֶמְיָנָא וְיַעְבְּדוּן לְבוּשֵׁי קוּדְשָׁא לְאַהֲרֹן אָחוּךְ וְלִבְנוֹהִי לְשַׁמָשָׁא קֳדָמַי:
@7 וְאִנוּן יִסְבוּן יָת דַהֲבָא וְיָת תִּכְלָא וְיָת אַרְגְוָנָא וְיָת צְבַע זְהוֹרִי וְיָת בּוּצָא:
@8 וְיַעְבְּדוּן יָת אֵפוֹדָא דַהֲבָא תִּכְלָא וְאַרְגְוָנָא צְבַע זְהוֹרִי וּבוּץ שְׁזִיר עוֹבַד אֳמָן:
@9 תַּרְתֵּין כַּתְפִּין מְלַפְּפָן יְהוֹן לֵהּ עַל תְּרֵין סִטְרוֹהִי וְיִתְלָפַף:
@10 וְהֶמְיַן תִּקוּנֵי דִי עֲלוֹהִי כְּעוֹבָדוֹהִי מִנֵהּ יְהֵי דַהֲבָא תִּכְלָא וְאַרְגְּוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר:
@11 וְתִסַב יָת תַּרְתֵּין אַבְנֵי בוּרְלָא וְתִגְלוֹף עֲלֵיהֶן שְׁמָהַת בְּנֵי יִשְׂרָאֵל:
@12 שִׁתָּא מִשְׁמָהָתְהוֹן עַל אַבְנָא חֲדָא וְיָת שְׁמָהַת שִׁתָּא דְאִשְׁתָּאָרוּ עַל אַבְנָא תִנְיֵתָא כְּתוּלְדָתְהוֹן:
@13 עוֹבַד אֳמָן אֶבֶן טָבָא כְּתַב מְפָרַשׁ כִּגְלֹף דְעִזְקָא תִגְלוֹף יָת תַּרְתֵּין אַבְנַיָא עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל מְשַׁקְעָן מְרַמְצָן דִדְהַב תַּעְבֵּד יָתְהוֹן:
@14 וּתְשַׁוִּי יָת תַּרְתֵּין אַבְנַיָא עַל כִּתְפֵּי אֵפוֹדָא אַבְנֵי דָכְרָנָא לִבְנֵי יִשְׂרָאֵל וְיִטּוֹל אַהֲרֹן יָת שְׁמָהָתְהוֹן קֳדָם יְיָ עַל תְּרֵין כִּתְפּוֹהִי לְדָכְרָנָא:
@15 וְתַעְבֵּד מְרַמְצָן דִדְהַב:
@16 וְתַרְתֵּין תִּכִּין דְהַב דְכֵי מְתַחְמָן תַּעְבֵד יָתְהוֹן עוֹבַד גְדִילוּ וְתִתֵּן יָת תִּכַּיָא גְדִילָתָא עַל מְרַמְצָתָא:
@17 וְתַעְבֵּד חשֶׁן דִינָא עוֹבַד אֳמָן כְּעוֹבַד אֵפוֹדָא תַּעְבְּדִנֵהּ דַהֲבָא תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי וּבוּץ שְׁזִיר תַּעְבֵּד יָתֵהּ:
@18 מְרַבַּע יְהֵי עֵיף זֶרְתָּא אֻרְכֵּה וְזֶרְתָּא פְתָיֵהּ:
@19 וְתַשְׁלֵם בֵּה אַשְׁלָמוּת אַבְנָא אַרְבְּעָא סִדְרִין אֶבֶן טָּבָא סִדְרָא קַדְמָאָה םַמְקָן יַרְקָן וּבַרְקָן סִדְרָא חָד:
@20 וְסִדְרָא תִּנְיָנָא אִזְמָרַגְדִין וְשַׁבְזִיז וְסִבְהֲלוֹם:
@21 וְסִדְרָא תְּלִיתָאָה קַנְכִּירֵי טַרְקְיָא וְעֵין עֶגְלָא:
@22 וְסִדְרֵא רְבִיעָאָה כְּרוּם יַמָא וּבוּרְלָא וּפַנְטֵרֵי מְרַמְצָן דִדְהַב יְהוֹן בְּאַשְׁלָמוּתְהוֹן:
@23 וְאַבְנַיָא יְהֶוְיַן עַל שְׁמָהַת בְּנֵי יִשְׂרָאֵל תַּרְתֵּי עֶסְרֵי עַל שְׁמָהַתְהוֹן כְּתַב מְפָרַשׁ כִּגְלוֹף דְעִזְקָא גְבַר עַל שְׁמֵהּ תְּהֶוְיָן לִתְרֵין עֲסַר שִׁבְטִין:
@24 וְתַעְבֵּד עַל חוּשְׁנָא תִּכִּין מְתַחְמָן עוֹבַד גְדִילוּ דְהַב דְכֵי:
@25 וְתַעְבֵּד עַל חוּשְׁנָא תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָת תַּרְתֵּין עִזְקָתָא עַל תְּרֵין סִטְרֵי חוּשְׁנָא:
@26 וְתִתֵּן יָת תַּרְתֵּין גְדִילָן דִדְהַב עַל תַּרְתֵּין עִזְקָתָא לְסִטְרֵי חוּשְׁנָא:
@27 וְיָת תַּרְתֵּין גְדִילָן דְעַל תַּרְתֵּין סִטְרוֹהִי תִּתֵּן עַל תַּרְתֵּין מְרַמְצָתָא וְתִתֵּן עַל כִּתְפֵּי אֵפוֹדָא לָקֳבֵל אַפּוֹהִי:
@28 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וּתְשַׁוִּי יָתְהוֹן עַל תְּרֵין סִטְרֵי חוּשְׁנָא עַל סִפְתֵהּ דִי לְעִבְרָא דְאֵפוֹדָא מִלְגָו:
@29 וְתַעְבֵּד תַּרְתֵּין עִזְקָן דִדְהַב וְתִתֵּן יָתְהוֹן עַל תַּרְתֵּין כִּתְפֵּי אֵפוֹדָא מִלְרַע מִלְקֳבֵל אַפּוֹהִי לָקֳבֵל בֵּית לוֹפֵי מֵעִלָוֵי לְהֶמְיַן אֵפוֹדָא:
@30 וְיֶחְדוּן יָת חוּשְׁנָא מֵעִזְקְתֵהּ לְעִזְקְתָא דְאֵפוֹדָא בְּחוּטָא דִתְכֶלְתָּא לְמֶהֱוֵי עַל הֶמְיַן אֵפוֹדָא וְלָא יִתְפָּרֵק חוּשְׁנָא מֵעִלָוֵי אֵפוֹדָא:
@31 וְיִטוֹל אַהֲרֹן יָת שְׁמָהַת בְּנֵי יִשְׂרָאֵל בְּחשֶׁן דִינָא עַל לִבֵּהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא לְדוּכְרָנָא קֳדָם יְיָ תְּדִירָא:
@32 וְתִתֵּן בְּחשֶׁן דִינָא יָת אוּרַיָא וְיָת תֻּמַיָא וִיהוֹן עַל לִבָּא דְאַהֲרֹן בְּמֵעֲלֵהּ קֳדָם יְיָ וְיִטוֹל אַהֲרֹן יָת דִינָא דִבְנֵי יִשְׂרָאֵל עַל לִבֵּהּ קֳדָם יְיָ תְּדִירָא:
@33 וְתַעְבֵּד יָת מְעִילָא דְאֵפוֹדָא גְמִיר תִּכְלָא:
@34 וִיהֵי פוּם רֵישֵׁהּ כָּפִיל לְגַוֵּהּ תּוֹרָא יְהֵא מַקַף לְפוּמֵהּ סְחוֹר סְחוֹר עוֹבַד מָחֵי כְּפוּם שִׂרְיָן יְהֵי לֵהּ לָא יִתְבְּזָע:
@35 וְתַעְבֵּד עַל שִׁיפוֹלוֹהִי רִמוֹנֵי תִּכְלָא וְאַרְגְוָנָא וּצְבַע זְהוֹרִי עַל שִׁיפוֹלוֹהִי סְחוֹר סְחוֹר וְזַגִין דְדַהֲבָא בֵּינֵיהוֹן סְחוֹר סְחוֹר:
@36 זַגָא דְדַהֲבָא וְרִמוֹנָא זַגָא דְדַהֲבָא וְרִמוֹנָא עַל שִׁיפוֹלֵי מְעִילָא סְחוֹר סְחוֹר:
@37 וִיהֵי עַל אַהֲרֹן לְשַׁמָשָׁא וְיִשְׁתְּמַע קָלֵהּ בְּמֵעֲלֵהּ לְקוּדְשָׁא קֳדָם יְיָ וּבְמִפְקֵהּ וְלָא יְמוּת:
@38 וְתַעְבֵּד צִיצָא דִדְהַב דְכֵי וְתִגְלוֹף עֲלוֹהִי כְּתַב מִפָרַשׁ קֹדֶשׁ לַיָי:
@39 וּתְשַׁוִי יָתֵהּ עַל חוּטָא דִתְכֶלְתָּא וִיהֵי עַל מִצְנֶפְתָּא לָקֳבֵל אַפֵּי מִצְנֶפְתָּא יְהֵי:
@40 וִיהֵי עַל בֵּית עֵינוֹהִי דְאַהֲרֹן וְיִטּוֹל אַהֲרֹן יָת עֲוָיַת קוּדְשַׁיָא דִי יְקַדְשׁוּן בְּנֵי יִשְׂרָאֵל לְכָל מַתְּנַּת קוּדְשֵׁיהוֹן וִיהֵי עַל בֵּית עֵינוֹהִי תְּדִירָא לְרַעֲוָא לְהוֹן קֳדָם יְיָ:
@41 וּתְרַמֵץ כִּתּוּנָא בוּצָא וְתַעְבֵּד מִצְנֶפְתָּא דְבוּצָא וְהֶמְיָנָא תַּעְבֵּד עוֹבַד צַיָר:
@42 וְלִבְנֵי אַהֲרֹן תַּעְבֵּד כִּתּוּנִין וְתַעְבֵּד לְהוֹן הֶמְיָנִין וְכוֹבָעִין תַּעְבֵּד לְהוֹן לִיקָר וּלְתֻשְׁבְּחָן:
@43 וְתַלְבֵּש יָתְהוֹן יָת אַהֲרֹן אָחוּךְ וְיָת בְּנוֹהִי עִמֵהּ וּתְרַבֵּי יָתְהוֹן וּתְקָרֵב יָת קֻרְבָּנְהוֹן וּתְקַדֵשׁ יָתְהוֹן וִישַׁמְשׁוּן קֳדָמַי:
@44 וְעִבֵד לְהוֹן מִכְנְסִין דְבוּץ לְכַסָאָה בְשַׂר עֶרְיְתָא מֵחַרְצָן וְעַד יַרְכָּן יְהוֹן:
@45 וִיהוֹן עַל אַהֲרֹן וְעַל בְּנוֹהִי בְּמֵעַלְהוֹן לְּמַשְׁכַּן זִמְנָא אוֹ בְמִקְרָבְהוֹן לְמַדְבְּחָא לְשַׁמָשָׁא בְקוּדְשָׁא וְלָא יְקַבְּלוּן חוֹבָא וִימוּתוּן קְיָם עָלָם לֵהּ וְלִבְנוֹהִי בַתְרוֹהִי:
@46 וְדֵין פִּתְגָמָא דִי תַעְבֵּד לְהוֹן לְקַדָשָׁא יָתְהוֹן לְשַׁמָשָׁא קֳדָמַי סַב תּוֹר חָד בַּר תּוֹרֵי וְדִכְרִין תְּרֵין שַׁלְמִין:
@47 וּלְחֵם פַּטִיר וּגְרִיצִין פַּטִּירִין דְפִילָן בִּמְשַׁח וְאֶסְפּוֹגִין פַּטִּירִין דִמְשִׁיחִין בִּמְשָׁח סֻלְתָּא חִטִין תַּעְבֵּד יָתְהוֹן:
@48 וְתִתֵּן יָתְהוֹן עַל סַלָא חַד וּתְקָרֵב יָתְהוֹן בְּסַלָא וְיָת תּוֹרָא וְיָת תְּרֵין דִכְרִין:
@49 וְיָת אַהֲרֹן וְיָת בְּנוֹהִי תְּקָרֵב לִתְרַע מַשְׁכַּן זִמְנָא וְתַסְחֵי יָתְהוֹן בְּמַיָא:
@50 וְתִסַב יָת לְבוּשַׁיָא וְתַלְבֵּשׁ יָת אַהֲרֹן יָת כִּתּוּנָא וְיָת מְעִיל אֵפוֹדָא וְיָת אֵפוֹדָא וְיָת חוּשְׁנָא וְתַתְקֵן לֵהּ בְּהֶמְיַן אֵפוֹדָא:
@51 וּתְשַׁוִי מִצְנֶפְתָּא עַל רֵישֵׁהּ וְתִתֵּן יָת כְּלִילָא דְקוּדְשָׁא עַל מִצְנֶפְתָּא:
@52 וְתִסַב יָת מִשְׁחָא דִרְבוּתָא וּתְרִיק עַל רֵישֵׁהּ וּתְרַבֵּהּ יָתֵהּ:
@53 וְיָת בְּנוֹהִי תְּקָרֵב וְתַלְבֵּשִׁנוּן כִּתּוּנִין:
@54 וּתְזָרֵז יָתְהוֹן הֶמְיָנִין אַהֲרֹן וּבְנוֹהִי וְתַתְקֵן לְהוֹן כּוֹבָעִין וּתְהֵי לְהוֹן כְּהֻנְתָּא לִקְיַם עָלָם וּתְקָרֵב קֻרְבָּנָא דְאַהֲרֹן וְקֻרְבָּנָא דִבְנוֹהִי:
@55 וּתְקָרֵב יָת תּוֹרָא לִקֳדָם מַשְׁכַּן זִמְנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ תּוֹרָא:
@56 וְתִכּוֹס יָת תּוֹרָא קֳדָם יְיָ בִּתְרַע מַשְׁכַּן זִמְנָא:
@57 וְתִסַב מִדְמָא דְתוֹרָא וְתִתֵּן עַל קַרְנַת מַדְבְּחָא בְּאֶצְבְּעָךְ וְיָת כָּל דְמָא תֵישׁוֹד לִיסוֹדָא דְמַדְבְּחָא:
@58 וְתִסַב יָת כָּל תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חִצְרָא דִעַל כַּבְדָא וְיָת תַּרְתֵּין כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְתַסֵיק לְמַדְבְּחָא:
@59 וְיָת בִּסְרָא דְתוֹרָא וְיָת מַשְׁכֵהּ וְיָת אוּכְלֵהּ תּוֹקִיד בְּנוּרָא מִבָּרָא לְמַשְׁרִיתָא חַטָאתָא הוּא:
@60 וְיָת דִכְרָא חַד תִּסַב וְיִסְמְכוּן אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@61 וְתִכּוֹס יָת דִכְרָא וְתִסַב יָת דְמֵהּ וְתִזְרוֹק עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@62 וְיָת דִכְרָא תְּפַלֵג לְאֵבָרוֹהִי וּתְחַלִיל גַּוֵהּ וּכְרָעוֹהִי וְתִתֵּן עַל אֵבָרוֹהִי וְעַל רֵישֵׁהּ:
@63 וְתַסֵיק יָת כָּל דִכְרָא לְמַדְבְּחָא עֲלָתָא הוּא קֳדָם יְיָ לְאִתְקַבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ הוּא:
@64 וְתִסַב יָת דִכְרָא תִנְיָנָא וְיִסְמוֹךְ אַהֲרֹן וּבְנוֹהִי יָת יְדֵיהוֹן עַל רֵישׁ דִכְרָא:
@65 וְתִכּוֹס יָת דִכְרָא וְתִסַב מִדְמֵהּ וְתִתֵּן עַל רוּם אוּדְנָא דְאַהֲרֹן וְעַל רוּם אוּדְנָא דִבְנוֹהִי דְיַמִינָא וְעַל אִלְיוֹן יְדֵיהוֹן דְיַמִינָא וְעַל אִלְיוֹן רַגְלֵיהוֹן דְיַמִינָא וְתִזְרוֹק יָת דְמָא עַל מַדְבְּחָא סְחוֹר סְחוֹר:
@66 וְתִסַב מִן דְמָא דִי עַל מַדְבְּחָא וּמִמִשְׁחָא דִרְבוּתָא וְתַדֵי עַל אַהֲרֹן וְעַל לְבוּשׁוֹהִי וְעַל בְּנוֹהִי וְעַל לְבוּשֵׁי בְנוֹהִי עִמֵהּ וְיִתְקַדַשׁ הוּא וּלְבוּשׁוֹהִי וּבְנוֹהִי וּלְבוּשֵׁי בְנוֹהִי עִמֵהּ:
@67 וְתִסַב מִן דִכְרָא תַּרְבָּא וְאַלִיתָא וְיָת תַּרְבָּא דְחָפֵי יָת גַוָא וְיָת חֲצַר כַּבְדָא וְיָת תַּרְתֵּן כָּלְיָן וְיָת תַּרְבָּא דִי עֲלֵיהֶן וְיָת שׁוֹקָא דְיַמִינָא אֲרֵי דְכַר קֻרְבָּנָא הוּא:
@68 וּפִתָּא דִלְחֵם חַד וּגְרִצְתָּא דִלְחֵם מְשַׁח חֲדָא וְאֶסְפּוֹג חָד מִסַלָא דְפַטִירַיָא דִי קֳדָם יְיָ:
@69 וּתְשַׁוֵי כֹלָא עַל יְדָא דְאַהֲרֹן וְעַל יְדָא דִבְנוֹהִי וּתְרִים יָתְהוֹן אֲרָמוּתָא קֳדָם יְיָ:
@70 וְתִסַב יָתְהוֹן מִידֵיהוֹן וְתַסֵיק לְמַדְבְּחָא עַל עֲלָתָא לְאִתְקַבָּלָא בְרַעֲוָא קֳדָם יְיָ קֻרְבָּנָא הוּא קֳדָם יְיָ:
@71 וְתִסַב יָת חֶדְיָא מִדְכַר קֻרְבָּנַיָא דִי לְאַהֲרֹן וּתְרִים יָתֵהּ אֲרָמוּתָא קֳדָם יְיָ וִיהֵי לָךְ לָחֳלָק:
@72 וּתְקַדֵשׁ יָת חֶדְיָא דַאֲרָמוּתָא וְיָת שׁוֹקָא דְאַפְרָשׁוּתָא דִי אִתָּרַם וְדִי אִתַּפְרָשׁ מִדְכַר קֻרְבָּנַיָא מִדִי לְאַהֲרֹן וּמִדִי לִבְנוֹהִי:
@73 וִיהֵי לְאַהֲרֹן וְלִבְנוֹהִי לִקְיַם עָלָם מִן בְּנֵי יִשְׂרָאֵל אֲרֵי אַפְרָשׁוּתָא הוּא וְאַפְרָשׁוּתָא יְהֵי מִן בְּנֵי יִשְׂרָאֵל מִנִכְסַת קוּדְשֵׁיהוֹן אַפְרָשׁוּתְהוֹן קֳדָם יְיָ:
@74 וּלְבוּשֵׁי קוּדְשָׁא דִי לְאַהֲרֹן יְהוֹן לִבְנוֹהִי בַּתְרוֹהִי לְדַכָּאָה בְהוֹן וּלְקָרָבָא בְהוֹן יָת קֻרְבָּנְהוֹן:
@75 שִׁבְעַת יוֹמִין יַלְבֵּשִׁנוּן כַּהֲנָא תְּחוֹתוֹהִי מִבְּנוֹהִי דִי יֵעוֹל לְמַשְׁכַּן זִמְנָא לְשַׁמָשָׁא בְקוּדְשָׁא:
@76 וְיָת דְכַר קֻרְבָּנַיָא תִּסָב וּתְבַשֵׁל יָת בִּסְרֵהּ בַּאֲתַר קַדִישׁ:
@77 וְיֵכוּל אַהֲרֹן וּבְנוֹהִי יָת בְּסַר דִכְרָא וְיָת לַחְמָא דִי בְסַלָא לִתְרַע מַשְׁכַּן זִמְנָא:
@78 וְיֵכְלוּן יָתְהוֹן דִי יִתְכַּפַּר בְּהוֹן לְקָרָבָא יָת קֻרְבָּנְהוֹן לְקַדָשָׁא יָתְהוֹן וְחִלוֹנַי לָא יֵיכוּל אֲרֵי קוּדְשָׁא אִנוּן:
@79 וְאִם יִשְׁתָּאַר מִבְּסַר קֻרְבָּנַיָא וּמִן לַחְמָא עַד צַפְרָא וְתוֹקִיד יָת דְאִשְׁתָּאַר בְּנוּרָא לָא יִתְאֲכֵל אֲרֵי קוּדְשָׁא הוּא:
@80 וְתַעְבֵּד לְאַהֲרֹן וְלִבְנוֹהִי כְּדֵין כְּכֹל דִי פַקֵּדִית יָתָךְ שִׁבְעַת יוֹמִין תְּקָרֵב קֻרְבָּנְהוֹן:
@81 וְתוֹרָא דְחַטָאתָא תַּעְבֵּד לְיוֹמָא עַל כִּפּוּרַיָא וּתְדַכֵּי עַל מַדְבְּחָא בְּכַפָּרוּתָךְ עֲלוֹהִי וּתְרַבֵּי יָתֵהּ לְקַדָשׁוּתֵהּ:
@82 שִׁבְעַת יוֹמִין תְּכַפֵּר עַל מַדְבְּחָא וּתְקַדֵשׁ יָתֵהּ וִיהֵי מַדְבְּחָא קֹדֶשׁ קוּדְשַׁיָא כָּל דְיִקְרַב בְּמַדְבְּחָא יִתְקַדָשׁ:
@83 וְדֵין דִי תַעְבֵּד עַל מַדְבְּחָא אִמְרִין בְּנֵי שְׁנָא תְּרֵין לְיוֹמָא תְּדִירָא:
@84 יָת אִמְרָא חַד תַּעְבֵּד בְּצַפְרָא וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא:
@85 וְעִסְרוֹנָא סֻלְתָּא דְפִילָא בִמְשַׁח כָּתִישָׁא רַבְעוּת הִינָא וְנִסְכָּא רַבְעוּת הִינָא חַמְרָא לְאִמְרָא חָד:
@86 וְיָת אִמְרָא תִנְיָנָא תַּעְבֵּד בֵּין שִׁמְשַׁיָא כְּמִנְחַת צַפְרָא וּכְנִסְכַּהּ תַּעְבֵּד לַהּ לְאִתְקַּבָּלָא בְרַעֲוָא קֻרְבָּנָא קֳדָם יְיָ:
@87 עֲלָתָא תְדִירָא לְדָרֵיכוֹן בִּתְרַע מַשְׁכַּן זִמְנָא קֳדָם יְיָ דִאֱזַמֵן מֵימְרִי לְכוֹן תַּמָן לְמַלָלָא עִמָךְ תַּמָן:
@88 וֶאֱזַמֵן מֵימְרִי תַמָן לִבְנֵי יִשְׂרָאֵל וְיִתְקַדַשׁ בִּיקָרִי:
@89 וֶאֱקַדֵשׁ יָת מַשְׁכַּן זִמְנָא וְיָת מַדְבְּחָא וְיָת אַהֲרֹן וְיָת בְּנוֹהִי אֱקַדֵשׁ לְשַׁמָשָׁא קֳדָמַי:
@90 וְאַשְׁרֵי שְׁכִנְתִּי בְּגוֹ בְּנֵי יִשְׂרָאֵל וְאֶהֱוֵי לְהוֹן לֶאֱלָהּ:
@91 וְיִדְעוּן אֲרֵי אֲנָא יְיָ אֱלָהֲהוֹן דִי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרַיִם לְאַשְׁרָאָה שְׁכִנְתִּי בֵּינֵיהוֹן אֲנָא יְיָ אֱלָהֲהוֹן:
@92 וְתַעְבֵד מַדְבְּחָא לְאַקְטָרָא עֲלוֹהִי קְטוֹרֶת בּוּסְמַיָא דְאָעֵי שִׁטִין תַּעְבֵּד יָתֵהּ:
@93 אַמְתָא אֻרְכֵּהּ וְאַמְתָא פְתָיֵהּ מְרַבַּע יְהֵי וְתַרְתֵּין אַמִין רוּמֵהּ מִנֵהּ קַרְנוֹהִי:
@94 וְתַחֲפֵי יָתֵהּ דְהַב דְכֵי יָת אִגָרֵהּ וְיָת כָּתְלוֹהִי סְחוֹר סְחוֹר וְיָת קַרְנוֹהִי וְתַעְבֵּד לֵהּ דֵיר דִדְהב סְחוֹר סְחוֹר:
@95 וְתַרְתֵּין עִזְקַן דִדְהַב תַּעְבֶּד לֵהּ מִלְרַע לְדֵירֵהּ עַל תַּרְתֵּין זִוְיָתֵהּ תַּעְבֵּד עַל תְּרֵין סִטְרוֹהִי וִיהֵי לְאַתְרָא לַאֲרִיחַיָא לְמִטַל יָתֵהּ בְּהוֹן:
@96 וְתַעְבֵּד יָת אֲרִיחַיָא דְאָעֵי שִׁטִין וְתַחֲפֵי יָתְהוֹן דַהֲבָא:
@97 וְתִתֵּן יָתֵה קֳדָם פָּרֻכְתָּא דִי עַל אֲרוֹנָא דְסַהֲדוּתָא לִקֳדָם כַּפֻּרְתָּא דִי עַל סַהֲדוּתָא דִי אֲזַמֵן מֵימְרִי לָךְ תַּמָן:
@98 וְיַקְטַר עֲלוֹהִי אַהֲרֹן קְטוֹרֶת בּוּסְמִין בִּצְפַר בִּצְפַר בְּאַתְקָנוּתֵהּ יָת בּוֹצִינַיָא יַסֵקִנַהּ:
@99 וּבְאַדְלָקוּת אַהֲרֹן יָת בּוֹצִינַיָא בֵּין שִׁמְשַׁיָא יַסֵקִנַהּ קְטוֹרֶת בּוּסְמַיָא תְדִירָא קֳדָם יְיָ לְדָרֵיכוֹן:
@100 לָא תַסְקוּן עֲלוֹהִי קְטוֹרֶת בּוּסְמִין נוּכְרָאִין וַעֲלָתָא וּמִנְחָתָא וְנִסְכָּא לָא תְנַסְכוּן עֲלוֹהִי:
@101 וִיכַפֵר אַהֲרֹן עַל קַרְנוֹהִי חֲדָא בְּשַׁתָּא מִדְמָא חַטַאת כִּפּוּרַיָא חֲדָא בְשַׁתָּא יְכַפֵּר עֲלוֹהִי לְדָרֵיכוֹן קֹדֶשׁ קוּדְשִׁין הוּא קֳדָם יְיָ: פפפ:

@1 **ואתה תצוה**. צריך לדעת למה הוצרך לומר ואתה אחר שעמו היה מדבר, עוד למה אמר תצוה ולא צו, עוד למה אמר לשון ציווי. ורבותינו ז''ל אמרו בזה דרשות מהם אמרו (תו''כ ס''פ אמוד) אין צו אלא זירוז לצד שיש חסרון כים, ואולי כי לצד שהדבר אינו מן המוסר לצוות ה' שידליקו נרות בבית ה' אשר ממנו תצא אורה, אשר על כן אמר למשה כי מצוה זו לא יאמרנה לישראל על פי ה' אלא הוא יצוה פירוש מפי עצמו שינהגו כבוד זה להביא שמן להדליק, ולזה אמר **ואתה**, פירוש מלבד מה שצויתיך הוסף אתה לצוותם על זה. ודקדק לומר **תצוה** ולא תדבר להצדיק דברינו אלה שיזרזם הוא על הדבר שאם אמר תדבר יהיה הנשמע כי ידבר דברי ה' כסדר הרגיל לדבר מבלי צורך הזירוז, ולזה לא אמר צו שאז יהיה נשמע שיאמר כי ה' אמר אליו לצוות אלא **תצוה** פירוש מעצמך. ולא יראה בעיניך כי מצוה זו קלה היא כיון שאינה אלא מפי משה לא כן הוא שאין זה אלא משום דרך כבוד לאל עליון אבל המצוה הרי אנו רואים כי ה' אמר אליו שיצוה. ואולי כי לזה אמר **ויקחו אליך** פירוש למה שאתה בדעתך תצוה. עוד ירצה לצד שצוה ה' כל מעשה המשכן וענייניו לנוכח שיראה שמצוה לו שיעשה הוא כל הנדבר אליו ויביא כל הנדבה אל המשכן לצד התלהבותו בעבודת ה' גם יעשה מלאכת המשכן ועבודתו, לזה אמר אליו **ואתה תצוה** פירוש מה שיש לך מהיתרון על כל ישראל אינו אלא מה שתצוה אותם לבד, ולזה אמר תיבת **ואתה** ותוספת הוא''ו לצד שיש עושים לבד משה, וידוייק גם כן אומרו **תצוה** ולא אמר צו:
@1 **עוד** ירמוז לצד כי הגיע זמן תת הכהונה לאהרן ברר ה' למשה המלכות והמליכו על ישראל, והוא אומרו **תצוה את בני ישראל**, על דרך אומרו (ש''א י''ג) ויצוהו ה' לנגיד וגו'. והגם שבארץ מצרים אמר הכתוב (לעיל ו' י''ג) ויצום אל בני ישראל ופירשנו שם שעשאם מושלים בעם כאן יחד משה למלכות ישראל ואהרן כהן. ואולי כי לזה נתכוון מה שאמר הכתוב (לעיל י''ט ו') ואתם תהיו לי ממלכת כהנים וגוי קדוש, ממלכת חוזר אל משה, כהנים אהרן ובניו, וגוי קדוש אלו הלוים. ואולי שירמוז באומרו **תצוה** על דרך אומרם ז''ל (זהר ח''א פ''ג) כי כל תלמיד חכם יש לו ניצוץ מנשמת משה, ולזה רבותינו ז''ל (סוכה ל''ט.) היו קוראים זה לזה משה כי הוא זה המדבר בבחינת נפש הלומדת תורה, והוא אומרו **ואתה תצוה** על דרך אומרו (תהלים צ''א) כי מלאכיו יצוה לך שהוא לשון צוותא ליווי לאיש ישראל הנכבדים, וכבר ידעת כי אין חשיבות אלא באמצעות עסק התורה. ובחר ה' לרמוז רמז זה במצוות שמן כי הוא בחינת התורה שהוא אור העולם. ועיין בפסוק שאחר זה:
@1 **ויקחו אליך**. טעם אומרו **אליך** יתבאר על דרך מה שאמרו במסכת שבת דף כ''ב וזה לשונם מחוץ לפרוכת העדות עדות היא לכל באי עולם שהשכינה שורה בישראל מאי עדות אמר רב זה נר המערבי כו' עד כאן. והנה אמרו ז''ל (שמו''ד פנ''ב) ליצני הדור היו מתלוצצים על משה לומר אפשר שהשכינה שורה על מעשה של משה וכו' עד כאן. הרי כי לא היו מצדיקים אפילו מישראל שתשרה שכינה במשכן וכפי זה הגם ששרתה שכינה ביום א' בניסן עם כל זה אין זה סימן לתמידות שתקבע השכינה מקומה במשכן אבל בנם נר המערבי הוא עדות לכל באי עולם שהשכינה שורה בישראל, והוא מאמר ה' **ויקחו אליך** פירוש אליך נוגע הדבר כי בזה תתחזק נבואתך שיכירו ויצדיקו נבואתך שהשכינה תשרה בתוכם כשיראו נם שיעשה בשמן המנורה. ואולי כי לזה נתכוון באומרו **ואתה תצוה** לומר שלא יחוש שלא יאמנו דבריו להיות הדבר תמוה שידור אל עליון בתחתונים וכמו שכן היה ואם תאמר מנין יצדיקו **ויקחו אליך** פירוש בדבר זה יש לך חיזוק והצדקת הדברים כנזכר:
@1 **ובדרך** רמז יתבאר הכתוב על דרך מאמר הובא בספר זוהר חדש (בראשית ח') כי ד' גליות של ישראל כל אחד מהם נגאלו ממנו בזכות אחד, גלות הראשון נגאלו בזכות אברהם אבינו עליו השלום, ב' נגאלו בזכות יצחק, ג' בזכות יעקב, והד' תלוי בזכות משה ולזה נתארך הגלות כי כל עוד שאין עוסקים בתורה ובמצות אין משה חפץ לגאול עם בטלנים מן התורה. וזה הוא שרמז הכתוב כאן באומרו **ואתה תצוה את בני ישראל** על דרך (תהלים צ''א) כי מלאכיו יצוה, או על דרך אומרם ז''ל אין צו אלא מלכות כי הוא ימלוך עלינו לעתיד ותנאי הוא הדבר שיעסקו ישראל בתורה. וזה הוא אומרו **ויקחו אליך שמן זית** זך ירמוז אל התורה שנמשלה לשמן מה השמן מאיר לעולם כך התורה והם דברי הזוהר שכתבנו בסמוך, ודקדק לומר **זך** שצריכין לעסוק בתורה לשמה בלי שמרים שהם לקנתר ח''ו או להתגדל וכדומה אלה הם שמריה. ואמר עוד **כתית** פירוש שצריכין לעסוק בתורה ולכתת גופם וכחם על דרך אומרו (במדבר יט יד) זאת התורה אדם כי ימות (ברכות ס''ג:) וכבר כתבתי ענין זה בחפצי (חפץ ה') בענין המיימינים בה יעויין שם. ואומרו **למאור** תתפרש גם כן כפי דרכנו כי בזמן הגלות נחשך מאור הלבנה שנקראת המאור הקטן ונפרד אלוף ממנה ושפחה תירש גבירתה, ולזה יצו כי יכוין בשמן זית להאיר למאור וליחדו במכון גם יכוין אל המאור הגדול, כי כבר ידעת מאמרם ז''ל (מגילה כ''ט.) בפסוק (דברים ל ג) ושב ה' ממה שלא אמר והשיב, גם מאמרם ז''ל (תענית ה'.) בפסוק לא אבא בעיר והבן. ואומרו **להעלות** וגו' עולה תמיד ותמיד זה אין לו שיעור ולא תשוב לדאבה עוד והיה לה ה' לאור עולם. ואולי שכיוון עוד לומר **למאור להעלות נר תמיד** כי המאור הגדול הוא יעלה הנר תמיד על דרך אומרו (ישעי' ס''ב) נשבע ה' וגו' אם אתן את דגנך והיית רק למעלה:
@2 **מאת בני ישראל**. יתבאר על דרך מה שאמרו בתוספתא דשקלים (פ''ב) כל קרבנות הציבור שנתנדבו מעצמן כשרים ובלבד שימסרום לציבור עד כאן לשונם, והוא מה שאמר הכתוב **מאת בני ישראל** פירוש כי שמן זה קרבן ציבור ולזה לו יהיה שיתנדבו יחיד צריך שימסרם לציבור ותהיה הבאתו למשכן מאת בני ישראל:
@3 **ואתה הקרב אליך**. טעם אומרו **ואתה**, גם אמר לשון הקרבה, גם אמר תיבת **אליך**, יתבאר על דרך אומרם ז''ל (שמו''ר פ''ג) כי הכהונה למשה היתה למנה אלא לצד שמאן ללכת בדבר ה' אחר כמה פעמים חרה ה' בו והסירו מגבירת הכהונה באומרו (לעיל ד' י''ד) הלא אהרן אחיך הלוי פירוש שהיה לוי ועכשיו נעשה כהן עד כאן. לזה אמר לו בשעת מעשה **ואתה** פירוש לא לצד שאני מצוך לבד אלא גם אתה מצד עצמך **הקרב** את אהרן במקומך ותעשה הדבר כאלו אתה חפץ בו כי זה לך במקום קרבן לכפרה על אשר העזת פניך לפני ה', ואומרו **אליך** לכפרתך בהקריב את אהרן ויתן לו גדולתו אין לך קרבן גדול מזה:
@3 **עוד** ירמוז באומרו **הקרב אליך** כי על ידי חטא האדם מתרחק בחינת עינף נשמתו שכנגד אותו ענף שבו חטא משורשו הגדול כפי גדלו והקטן כו', והנה באמצעות ההפצרות שהפציר בשליחות ה' גרם להתרחקות ענף אחד מענפי נשמתו משורשה, והגם כי ה' הענישו אף על פי כן כל עוד שלא קיבל העונש הפגם עומד במקומו והרחוק עודנו מרוחק, לזה בשעת תכלית הדבר הודיעו כי בזה יהיה מתקרב הרחוק, והוא אומרו **ואתה הקרב אליך** פירוש הקרב לעצמך פירוש לבחינתך שרחוקה באמצעות החטא ההוא, ונתכוון ה' להודיעו כי זה תיקונו, ומזה אני משכיל על דבר שאמרו ז''ל בסוף ברכות (נ''ד.) חייב אדם לברך על הרעה כשם שהוא מברך על הטובה וכו' ומפרש בגמרא (שם ס':) לקבל הרעה בשמחה כשם ששמח בטובה עד כאן. והיה הדבר קצת בעיני רחוק, ועל פי הדברים האמורים בענין הנה היסורין הם מקריבין ענפי הנשמה שהיו רחוקים משורשם, שאין לך רע ומר כעוזבו את ה' אלהיו, ובאמצעות היסורין יתקרב הרחוק ועל זה ישמח לב המשכיל, ואמר **ועשית בגדי קודש** וגו' **לכבוד ולתפארת** שהם הם סימני השמחה שיראה שחפץ ודבר לפארו, אשר זה הוא שנאוי לעושה הדבר לצד ההכרח, והגם שהבגדים הם חובת גברא העומד לשרת, עם כל זה רצה ה' לזכות לגלגל זכות זה על ידו שיעשה אותם לחיבה ולשמחה באחיו, ודבר זה הוא בחינת נשמה לנשמה בעיקר מעשה זה, ואולי שנתכוון ה' לומר לו שיעשה הבגדים משלו, והגם ששנינו (יומא פ''ג מ''ז) בגדי הכהנים באים משל ציבור, הרי אמרו שיחיד יכול להתנדבם ולמוסרם לציבור וכמו כן צוה ה' לעשות:
@4 **ועשית וגו' לכבוד ולתפארת**. צריך לדעת מה היא כוונת ה' באומרו **לכבוד** וגו' אחר שמודיע מעשיהם ואופניהם, ואם להודיעו שבגדים אלו יש בהם לאהרן כבוד ותפארת מה יצא לנו מזה. ואולי שיתבאר על פי מה שאמרו בפרק אין מעמידין (ע''ז ל''ד.) וזה לשונם שאלו את רבי עקיבא במה שמש משה שבעת ימי המילואים לא הוה בידיה אתא ושאל בי מדרשא אמר ליה בחלוק לבן שאין בו אמרא עד כאן. הנה ממה ששמש משה בשבעת ימי המילואים בחלוק זה יגיד שאין הבגדים מעכבין אלא לאהרן ולבניו אבל זולת הכהנים תתרצה עבודת הקרבנות בלא בגדים, והוא מה שמודיעו באומרו **כבוד** וגו' לומר לא תחשוב כי הבגדים לצורכי עבודה לבד ויתחייב הדבר ללובשם משה בעבודת ימי המילואים ולא כן הוא אינם אלא לכבוד וגו' למשרת קבוע לעבודתו אבל לצד העבודה לבד כשתהיה בזולת אהרן ובניו יעבדו בחלוק לבן וכמו שכן שמש משה כנזכר:
@4 **או** יאמר כי בא ה' לתת טעם למה צוה ח' בגדים ד' לבן וד' זהב ואמר הטעם הוא **לכבוד ולתפארת** פירוש על פי דבריהם ז''ל (הקדמת תיקונים) כי הח' בגדים ד' של בגדי לבן ירמזו אל ד' אותיות של שם הוי''ה ברוך הוא וד' בגדי זהב ירמזו אל ד' אותיות של שם אדנ''י, ודע כי שם הוי''ה ברוך הוא יתיחם אליו כינוי התפארת כידוע ושם אדנ''י יתיחס אליו כינוי הכבוד, והוא אומרו **ועשית בגדי קודש** וגו' **לכבוד** כנגד בגדי זהב **ולתפארת** כנגד בגדי לבן, וסדר הכתוב סדר הדרגות הקדושה זו למעלה מזו והקדים **לכבוד** והבן. וצוה ה' עשות ח' בגדים שבאמצעותם יתכפר פגמים אשר יסבבו בני האדם אשר יגיע למקום עליון ובזה יכופר העון ההוא. ולדרך זה יש לתת טוב טעם למה הקפיד ה' על הבגדים באהרן ולא במשה על דרך אומרם ז''ל (ערכין ט''ז.) כי ח' בגדי כהונה מכפדים על ח' מיני עבירות שיהיה בבני ישראל אשר על כן לא צוה ה' הדבר אלא להכהן העומד לשרת הוא ובניו כל הימים לכפר על בני ישראל מה שאין כן משה שכל מה ששמש בז' ימי המילואים לא היה אלא לכפרת אהרן ובניו למלא את ידם לעבוד לפני ה' לא היה צורך למה שיכפרו הבגדים כנזכר לזה שמש בחלוק וגו':
@5 **ואתה תדבר**. טעם אומרו **ואתה**, שצריך הוא בעצמו להתטפל בדבר לדבר לחכמי לב, והגם שאמר ועשית בגדי וגו' חזר ה' ופירש דבריו כי לא הוא יעשה אלא על פיו יהיו נעשים וכדי שלא יבין שהעיקר הוא שיהיו נעשים על פי משה ואין צורך בדבר שידבר משה מפיו אל חכמי לב לזה באה המצוה ואמר **ואתה** בפיך **תדבר אל כל** וגו', ודקדק לומר **אל כל** כי זה הוא אחד מסימנים המובהקים שהדבר הוא מהשלמת הדעת ומרצון הלב שידבר הדברים לכולם יחד שאם היה הדבר בא בדאבון נפש ישתדל לומר הדברים שלא בפני רבים וכל עוד שיכול לדבר דבריו לפני אחד לא ידבר בפני שנים כי הדבר הוא פחיתות למשה שלא יהיה הוא ראוי לשרת לפני המלך, אשר על כן צוה ה' לעשות סימן לדבר אל כל חכמי לב ובזה יוודע לעיני הכל כי נפש חפצה ולב שלם:
@5 **עוד** נראה כי טעם שאמר ה' בה' פסוקים אלו ג' פעמים **ואתה** כי בא לתת לו מעלה בג' דברים והם נדבת המשכן בכללותיה א', ומלאכת המשכן וכליו ובגדי כהונה א', ועבודת בית המקדש א'. ואמר ה' אליו כי הוא נוטל שכר כאילו הוא עשה הכל, כנגד הבאת נדבת המשכן אמר **ואתה תצוה** וגו' ואליך הם מביאין והוא מה שגמר. אומר **ויקחו אליך** פירוש אני לך מצוה להביא והם יביאו אליך לעשות, וכנגד מלאכת המשכן אמר **ואתה תדבר אל כל חכמי לב** ובזה אינם אלא שלוחיך. ודקדק לומר **אל כל** כדי שכל המעשים שיהיו נעשים במשכן יהיו נעשים בשליחותך וכאילו הוא עשאם, וכנגד עבודת בית ה' אמר **ואתה הקרב אליך את אהרן** וגו' שיבא ויעבוד בשליחותך, ולזה דקדק לומר **אליך**, ולטעם זה מצוה ה' אל משה כל מעשה המשכן ומלאכתו ועבודתו לנוכח כי אחר האמת עליו הוא המצוה אלא שצוה לו שהוא יצוה אחרים במקומו:
@6 **ואלה הבגדים וגו'**. קשה למה לא מנה הכתוב אלא ששה בגדים והשמיט ציץ הקודש ומכנסיים. ואולי שרמזם הכתוב שניהם, הציץ רמזו בפסוק שלפני זה **ועשו את בגדי אהרן לקדשו** שלא היה נצרך לומר אלא ואלה הבגדים וגו' אלא נתכוין אל הציץ שלא הזכיר בפסוק ואלה הבגדים. ולזה אמר לאהרן ולא הזכיר לבניו כי לא נתכוין אלא על הציץ, ואומרו לשון רבים לצד שהוא לבדו לא יועיל כי ח' בגדים מעכבין זה את זה לכן אמר עליו לשון רבים, ובזה ידוייק גם כן אומרו **ואלה** שנראה כמוסיף על בגדים אחרים, לצד שכבר קדם וצוה על קצת ולא הוצרך לבאר כי סמך על מה שעתיד הוא לפרטם אחד אחד ובפרטן תמצא מבואר הרמוז, וכנגד המכנסיים אחר שהזכיר אלה הבגדים וגו' אמר **ועשו בגדי קודש**.
@6 **לאהרן אחיך ולבניו** ופסוק זה מיותר הוא לומר על המכנסיים, ולזה הזכיר **אהרן ובניו** כי המכנסיים צריכין בין לכהן גדול בין לכהן הדיוט. ונשאר לדעת למה לא סדרם הכתוב יחד עם הששה ולא היה צריך לכל זה, ואולי ב' דברים אלו אינם בגדר אחד עם הששה, הציץ לצד מעלתו יותר מג' בגדי כהן גדול ולזה הקדימו בפני עצמו, והמכנסיים לצד היותם בהדרגה פחותה מג' בגדי כהן הדיוט, ולזה איחרו בפני עצמו, והששה הם הדרגה שוה. עוד נראה טעם עשותו ככה שנתכוון לומר שצריך לעשות בגדי כהונה לשמן, לזה פרט בפסוק **ועשו בגדי קודש** שפירשנוהו במכנסיים ואמר **לאהרן אחיך ולבניו לכהנו לי** פירוש שצריך לעשותם לשם אהרן לשרת לפני ה' ומזה תלמוד לשאר בגדים. ובפסוק ראשון שפירשנו בציץ אמר.
@6 **לקדשו** וגו' כי מלבד שיעשהו לשם כהונה עוד יוסיף לכתוב בו קודש לה':
@11 **ולקחת את שתי וגו'**. צריך לדעת למה אמר **את** וגו'. ואולי שיכוין אל אבני שוהם שכבר הזכיר בתחלת המצוה בפרשת תרומה. וזה הוא שיעור הכתוב **ולקחת את שתי אבני שוהם** אשר צויתיך להביא. ובזה נתכוין במתק דבריו יתברך לתת לו טעם למה פרט אבני שוהם מכלל כל האבנים, כי אבני שוהם יש בהם מצוה אחת פרטית מלבד אבני המילואים, ולזה אמר אליו **ולקחת אותם אבני שוהם** שפרטתי לך:
@12 **ששה משמותם וגו'**. צריך לדעת למה אמר **משמותם** ולא אמר ששה שמות וגו' וששה שמות על וגו' כתולדותם. גם לא היה צריך לומר הנותרים כי רואה אני שנותרים הם. ובהכרח לפרש **נותרים** הפחותים על דרך אומרו על אלעזר וגו' הנותרים ודרשו ז''ל (יומא פ''ז זהר ח''ג נ''ו:) הפחותים כו' וכמו שדרשו גם כן (ב''ר פע''ג) בפסוק צאן לבן הנותרות יעויין שם, וזה יבהיל כי מאומרו **כתולדותם** משמע כסדר שנולדו ליעקב ואם כן למה הנולדים באחרונה פחותים מהדאשונים ומה גם שיש באחרונים בני הגבירות יוסף ובנימין זבולון ויששכר בן תורה ויש בראשונים מבני השפחות ואיך יקרא הכתוב לבני הגבירה נותרים בערך בני השפחות. ולהבין הענין אל זה אביט למה שאמרו בסוטה (ל''ו.) וזה לשונם ת''ר שתי אבנים היו לכהן גדול על כתפו וגו' ושמות בני ישראל כתוב עליהן ששה על אבן זו וששה על אבן זו שנאמר ששה וגו' שניה כתולדותם ולא ראשונה כתולדותם מפני שיהודה מוקדם ונ' אותיות כ''ה על אבן זו וכ''ה על אבן זו ר' חנינא בן גמליאל אומר לא כדרך שחלוקים בחומש הפקודים, אלא כדרך שחלוקים בחומש ב', כיצד בני לאה כסדרן בני רחל אחד מכאן ואחד מכאן ובני השפחות באמצע ואלא מה אני מקיים כתולדותם כשמותם שקרא להם יעקב ולא כשמות שקרא להם משה ראובני שמעוני וגו' עד כאן, פשטן של דברים הוא כי לתנא קמא כתולדותם חוזר על שמות ב' האבנים אלא שיקדימו יהודה לראובן על זה הדרך יהודה ראובן שמעון לוי דן נפתלי באבן אחת ובאבן השנית גד אשר יששכר זבולן יוסף ובנימין כסדר לידתן, וכשתחשוב האותיות תמצא כ''ה באחת וכ''ד באחת, ואמרו בש''ס (שם) ר' יצחק אמר הוסיף לו יהוס''ף, רב נחמן אמר בנימין מלא, וחשבון זה לא נרמז בפסוק אלא שכך באה להם הקבלה כ''ה באחת וכ''ה באחת. והקדמת יהודה לראובן אני אומר כי מהכתוב דורש לה ממה שכתב כתולדותם באחרונה ולא כתב על זה הדרך ופתחת עליהם שמות בני ישראל כתולדותם ואז יהיה נשמע שבאה מצות כתולדותם על סדר ב' האבנים. ואין להקשות מי גילה כי מה שאבן ראשונה אינה כתולדותם הוא לצד הקדמת יהודה ודלמא לומר שאין בהם סדר כל עיקר, זה אינו כי בהכרח כשתבוא לומר באבן ראשונה סדר אחר שאינו כתולדותם תבחר באחד מהסדרים שישנם בכתוב או סדר שכתוב בחומש הפקודים או בחומש שני ולכל אחד מהם כשתבוא לסדר אבן ראשונה שלא כתולדותם תצא בהכרח אבן השנית שלא כתולדותם ואם כן הרי בטלת כתולדותם בב' האבנים אשר על כרחך תתחייב לומר שהשינוי שמבטל כתולדותם באבן ראשונה הוא באופן שאינו מבטל גם בשניה והיכי דמי בהכרח בכהאי גוונא שיקדים יהודה ודבר זה סברא הוא כי הוא מלך ולו ראוי להקדים וגם מצינו לו שקדם בהקרבת חנוכת המזבח, והגם שגם יששכר קדם, אם באנו להקדימו כאן הרי בטלנו כתולדותם של אבן שניה, ולדרך זה מה שדקדקנו בפ' במקומו מונח. ואפשר לומר כי נתכוין לומר שאין הסדר מפסיל באבני האפוד שאם הקדים שמעון לראובן אינו מעכב, לזה אמר **ששה משמותם** וגו', **ואת שמות** וגו' **הנותרים** פירוש אין לכתוב אלא הנותר בידך שלא כתבת אותו על הראשונה. ויש להוכיח כן ממה שלא תנא בתוספתא דמנחות (פ''ה) סדר כתיבת השמות מעכבין זה את זה כדתני בגדי כהנים מעכבין זה את זה אבני שהם ואבני מילואים מעכבין זה את זה כתב שעל גביהן מעכבין זה את זה היה לו לומר גם כן סדר השמות מעכבין זה את זה אפשר שסובר שאין מעכב:
@12 **ור'** חנינא בן גמליאל סובר באבן ראשון בני לאה כולן כסדרן פירוש ואין להקדים בני זלפה הגם שקדמו בלידה ובשניה בנימין בראש האבן קודם בני השפחות שכן כתוב בחומש ב' ואחריו בני השפחות כסדר לידתן ויוסף בסוף האבן והוא אומרו אחד מכאן, ולפי סדר זה נמצא חשבון האותיות אינם חלוקים כ''ה על אבן זו וכ''ה על אבן זו כי אבן ראשונה שבה בני לאה כסדרן יש בה כ''ח אותיות ובאבן שניה כ''א ולכשתוסיף האות או ה''א ביוסף או יו''ד בבנימין יהיו כ''ב ולסברא זו יתבאר מה שדקדקנו בכתוב על זה הדרך **ששה משמותם** פירוש שלא כסדרן מהם שנולדו תחילה ומהם שנולדו אחר הששה הנותרים והם יששכר וזבולן שנולדו אחר כל בני השפחות, ואומרו **הנותרים** פירוש שנעשו נותר מסדר החשבון כשתבוא לסדר סדר הנולדים תחילה תמצא שהב' קדמו לב' בני לאה והותירם ה' אחריהם ולזה קרא להם נותרים, והגם שעמהם יוסף ובנימין אמר הנותרים לצד הארבעה שבהם:
@12 **ואבוא** אל העין מה שכתב הרמב''ם בפ' ט' מהלכות כלי המקדש וזה לשונו ששה על אבן זו וששה על אבן זו וכותבין שם יהוסף ונמצא כ''ה אותיות באבן זו וכ''ה אותיות אותיות באבן זו וכך היו כותבין. עד כאן. ודבריו ז''ל אינם לא כתנא קמא ולא כר' חנינא בן גמליאל אין זה אלא בנין חדש ולא כסברת רב כהנא שהביא הש''ס ודחאה שהוא אמר באבן ראשונה ראור.... ן גד אשר זבולון דן נפתלי ובאבן הב' שמעון לוי יהודה יששכר יוסף בנימין וגו', ומהרי''ק (בכ''מ) דחק ופירש כי פסק רמב''ם כר' חנינא בן גמליאל ומפרש דברי ר' חנינא בן גמליאל על זה האופן בני לאה כסדרן פירוש אחד כאן ואחד כאן בני רחל אחד מכאן ואחד מכאן בשני קצוות האבנים מלמטה ובני השפחות באמצע פירוש באמצע ב' האבנים עד כאן:
@12 **ולי** נראה שאין דברים אלו מתקבלים בלב כל חכם לב מד' טעמים, א' איך יניח תנא קמא ויפסוק כר' חנינא, ומה שאמר הרב שטעמו של ר' חנינא בן גמליאל מסתבר אדרבה טעמו דר' חנינא בן גמליאל לא מסתבר כלל דמפיק הכתוב ממשמעותו שפירש כתולדותם כשמות שקרא להם אביהם ולא כשמות שקרא להם משה כי מנין יעלה על דעת אנוש שיכתוב ראובני וגדי שיוצרך למעטם, ועוד כתולדותם לא משמע שפיר שרצונו לומר על שמותם בלידתם ואין הכרח להוציא התיבה מפשטה שהוא כסדר לידתם כסברת תנא קמא ויותר מסתבר טעמיה דתנא קמא. וקושיא זו קלה ממה שלאחריה, ב' לסברת הרב שאמר שבני לאה אחד מכאן כבני רחל למה אמר ר' חנינא בן גמליאל בני לאה כסדרן בני רחל אחד מכאן ואחד מכאן שמורה באצבע שבני לאה אינם אחד מכאן ואחד מכאן שאם פירוש כסדרן הוא אחד מכאן ואחד מכאן גם בני רחל כסדרן של בני לאה הם ולא היה לו לומר אלא בני רחל לבסוף, ועוד משמעות אחד מכאן ואחד מכאן לא יגיד כדבריו כי היה לו לומר אחד באבן זו ואחד באבן זו כי אחד מכאן וכו' יגיד כדברי רש''י שהוא אחד בראש האבן ואחד בסופה, וקושיא זו קלה משלאחריה, ג' כפי פירוש דברי הרב אין סדר זה בחומש שני כי בחומש ב' בני לאה בזה אחר זה ובנימין אחריהם ובני השפחות אחר בנימין ויוסף לבסוף ולר' חנינא בן גמליאל לדברי רמב''ם יוסף אחר ב' בני השפחות באבן הראשונה ובנימין מאוחר אחר שני בני השפחות האחרונים באבן השנית ואיך קאמר ר' חנינא בן גמליאל כדרך שחלוקים בחומש שני והלא בחומש שני בנימין קודם כל בני השפחו':
@12 **ועוד** למה הקדים יוסף לבנימין והלא בחומש ב' בנימין קודם, ואין לדחות שהפכם כדי לדייק חשבון כ''ה בכל אבן שהרי חשבונם שוה הוא ה' בכל אחד. ובאמת אם יעמוד ר' חנינא בן גמליאל ויאמר כי לכך נתכוון לא יוצדקו דבריו כיון שתלה הדבר ואמר כדרך שחלוקים בחומש ב', וגם אין דבריו מתקבלין כי הכתוב הקדים בנימין לבני השפחות ולדבריו הוא באחרונה שבאחרונות, הד' מנין מצא רמב''ם לסדר בני לאה חצים באבן זו וחצים באבן זו הלא פשטן של דברים שאמר ר' חנינא בן גמליאל בני לאה כסדרן לא משמע כן ומנין נתהוה לרמב''ם סברא זו בדברי ר' חנינא בן גמליאל. ואחרון הכביד מה שכתב הכסף משנה בטעם רמב''ם שכתב להשלים החמשים אותיות בתוספות ה''א ביוסף והקשה על זה מהש''ם דקאמר התם וזה לשונם הני חמשים חמשים נכי חדא הויין אמר רבי יצחק יוסף הוסיפו לו אות אחת שנאמר עדות ביהוסף מתקיף לה רב נחמן כתולדותם בעינן אלא בכל התורה בנימן והכא בנימ. ן שלם דכתיב ואביו קרא לו בנימין עד כאן הרי שדחה הש''ס תירוץ יהוסף דלא מתוקמא יהוסף והעלה אלא בנימין כתוב בב' יודין. ותירץ הרב כי קושית הש''ס מתולדותם לא הוי אלא לסברת תנא קמא אבל לדעתיה דר' חנינא בן גמליאל לא מקשה כי הוא לא אמר ששלל כתולדותם אלא שלא יכתוב ראובני שמעוני וכיון שכן אוקימתא ראשונה דיהוסף במקומה עומדת ורבינו פסק כר' חנינא בן גמליאל כנזכר עד כאן:
@12 **ודבריו** תמוהים בעיני עד למאוד הלא לדעת תנא קמא לא דקדק בשמות כלל ומפרש תיבת כתולדותם על סדר לידתם ראשון ראשון ומה מקום להקשות הש''ס לדעת תנא קמא מכתולדותם, אלא ודאי שלא הקשה מעיקרא אלא לדעת ר' חנינא בן גמליאל שמפרש כתולדותם כשמות שקרא להם אביהם ותירץ רב נחמן בנימין מלא. ולכשנניח הנחה סוברת כי תהיה הקושיא לדעת תנא קמא כל שכן וקל וחומר שתהיה לסברת ר' חנינא בן גמליאל שמדייק כתולדותם על השמות. ועוד מדברי רמב''ם מוכח שמפרש כתולדותם על הסדר ולא על השמות שכתב וזה לשונו ששה על אבן זו וששה על אבן זו כתולדותם עד כאן, ואם היתה כונת רמב''ם לפסוק כר' חנינא בן גמליאל לא היה סותם לומר כתולדותם שמצינו ראינו כי הש''ס הקשה אותה והוצרך לפרשה אלא ודאי שלא פסק כר' חנינא בן גמליאל אשר ע''כ יותר היה נכון להניח הדבר בצריך עיון מלומר כזה:
@12 **ואפשר** לומר כי רמב''ם לא גרס במילתיה דתנא קמא מפני שיהודה ראשון אלא על זה הדרך שניה **כתולדותם** פירוש בהצטרפות שניה הוא שיהיו נמצאים סדורים כתולדותם על זה הדרך ראובן באחת שמעון בשניה לוי באחת יהודה בשניה וכן על זה הדרך, נמצאת כשאתה בא לקרותם בסדר ב' שורות יהיו כתולדותם והוא אומרו שניה כתולדותם אבל ראשונה אינה כתולדותם כי הם סדורים בה על זה הדרך ראובן לוי יששכר ואין זה כתולדותם בשום אופן, ופירוש **כתולדותם** לפנינו ב' דרכים, הא' הוא סדר חומש הפקודים שהוא על זה הדרך בני לאה יחד בני רחל אחריהם בני השפחות אחריהן, והב' האמור בחומש ב' בני לאה ראשונים בני השפחות באחרונה בני רחל יוסף לבסוף ובנימין בין בני לאה ובין בני השפחות, ותנא קמא לא ביאר במה בחר, והגם שאמר כתולדותם אין הוכחה לסברתו כי יכול ליאמר כתולדותם הגם שיקדים כל בני לאה לצד שלא יפסיק בין בני אם אחת והגם שהמיעוט מהם נולדו אחר בני בלהה יכול ליאמר כתולדותם בסדר האמהות לאה ילדה ראשונה וכל הבנים יחשבו כבן א' להקדים כולם יחד, או גם כן לצד שרוב הבנים הם קדמו, וגם לצד שלא מצינו שנסדרו בכל התורה כולה כסדר לידתן על זה האופן, ודייק רמב''ם דברי ר' חנינא בן גמליאל שאמר לא כסדר שחלוקים בחומש הפקודים חלוקים וכו' זה יגיד כי דבר זה יכול ליכנס בדברי תנא קמא שבא לשלול אותו וזה לך האות כי כוונת תנא קמא באומרו כתולדותם שהוא באחד מב' הדרכים או כסדר חומש הפקודים או סדר חומש ב' ובא ר' חנינא בן גמליאל ושלל חומש הפקודים ובחר בחומש ב', וסבר רמב''ם שאין הכרח בדברי תנא קמא ואפשר שכך היא דעת תנא קמא לפרש בו כסדר חומש הפקודים, והגם שמדברי ר' חנינא בן גמליאל נראה כי תנא קמא סובר כן, להיות שדבריו שקולים הם לזה הוצרך לבאר אבל אנו אין לנו לפרש בדברי תנא קמא אלא כדעת ר' חנינא בן גמליאל כל שלא נמצא בפירוש שחלק עליו. ומחלוקת ר' חנינא בן גמליאל ותנא קמא היא במשמעות כתולדותם תנא קמא סובר שני' כתולדותם ע''ד שפירשנו אבל ר' חנינא בן גמליאל אמר בני לאה כסדרן פירוש באבן אחת בני (יוסף) [רחל] א' בראש האבן וא' בסוף ובני השפחות באמצע האבן אם כן אינם כתולדותם והוצרך לפרש כשמות וגו'. ופסק הרב כתנא קמא וסדר בני לאה א' באבן זו וא' באבן זו כדי שתבוא השניה כתולדותם ובני השפחות אחריהם כסדר הנזכר, וטעם שהקדימם כי הם נסדרו בחומש ב' קודם יוסף וגם בזה יצדק אומרו כתולדותם שאם יקדים יוסף ובנימין אז אפילו השניה אינם כתולדותם שהרי קדמו בני רחל לבני השפחות. וטעם שהקדים נפתלי לדן להשלים כ''ה אותיות כמו שאמר תנא קמא כי לא ר' חנינא בן גמליאל אמר דבר זה, והגם שיש מקום לומר כי מן הסתם אינו חולק מאמצעות הדברים תתחייב לומר שחולק כיון שחלק אותם בסדר שיהיו כ''ח באחת וכ''ב באחת. ואחר כך סדר יוסף ובנימין והשלים המנין באות ביהוסף כי לא דחה התלמוד סברא זו אלא לר' חנינא בן גמליאל אבל לא לתנא קמא כי אינו מפרש כתולדותם על השמות. ולא כתב יהודה בתחלה כי לא גרם לה בש''ם כמו שכתבנו, זה הוא מה שנראה לדחוק ליישב הברייתא לסברת רמב''ם. ואולי שנזדמנה לו איזה ברייתא ופסק אותה. ויהי מה לדרך זו של רמב''ם יתיישבו הדקדוקים שדקדקנו בכתוב על נכון. אומרו **ששה משמותם** ולא אמר ו' שמות שאז תבין שהם כסדרן כתולדותם בכל אבן ואבן אלא **משמותם** פירוש מכל ב' וב' מהם תקח אחד ותכתבנו על האבן הא' ויהיה נותר א' וכן לזוג הב' והג' וכו' ואחר כך תקח אותם הו' שנותרו מכל זוג וזוג ויהיה על האבן הב', ועל זה דקדק לומר **ואת שמות הששה הנותרים** פירוש שנותרו בידך כאמור, וכפי זה אומרו **כתולדותם** הוא על סדרן בב' האבנים ולזה איחר לומר **כתולדותם** אחר שהזכיר ב' האבנים והבן:
@37 **ובצאתו ולא ימות**. נראה שאם לא היו לו הפעמונים שמשמיעים את הקול חייב מיתה לשמים שאם לא כן ולא היתה כוונתו אלא למחוסר בגדים היה אומר ולא ימות אחר תשלום הבגדים או לפחות אחר תשלום ד' בגדי כהן גדול ולא באמצע אלא ללמד על הפרט בא שחייב אפילו על הפעמונים, ובפסוק האמור בסוף מעשה הבגדים דכתיב והיו על אהרן וגו' ולא ישאו עון ומתו שם חייב על העובד מחוסר בגדים:
@38 **קדש לה'**. משמע שכל מציאות שיכתוב קדש לה' כשר, ומה שאמרו בגמרא (שבת ס''ג:) שהיה כתוב שני שיטין יו''ד ה''א למעלה קדש לה' למטה לא לעכובא. ולזה תמצא שם שאמר ר' אליעזר בר' יוסי אני ראיתיו ברומי כתוב עליו קודש לה' בשיטה אחת וגו' הרי שאין הדבר מעכב ואפילו לתנא קמא אינו מעכב, ובזה לא יקשה בעיניך פסק רמב''ם פרק ט' מהל' כלי בית המקדש יע''ש:
@40 **לרצון להם לפני ה'**. צריך לדעת מה ענין יגידו ב' תיבות אלו שבהם יהיה לרצון לפני ה', ואולי שיכוון באומרו **קדש** על ישראל כאומרו (ירמי' כ') קדש ישראל, ותיבת **לה'** ירצה כי כללות ישראל הנקראים קדש הם לה' חשוקים דבוקים משועבדים ולזה יהיה **לרצון לפני ה'** שיש לו רצון בישראל באמצעות הכתב, והוא סוד (שה''ש ו) אני לדודי ובזה יתרצה דודי לי:
@42 **לכבוד ולתפארת**. טעם שאמר כן פעם ב' לרמוז מה שאמרו בזבחים (י''ח:) וזה לשונם היו מטושטשין או מקורעין ועבד עבודתו פסולה. ותניא עוד שם בד שיהיו חדשים. ואמרו בש''ם חדשים אין שחקים לא והתניא משוחקים כשרים וכו' אלא למצוה וכו', והוא או' **לכבוד** כנגד קרועים וזה לעכובא, **ולתפארת** כנגד חדשים וזה למצוה, ולזה הוצרך הכתוב לומר שניהם וזולת זה היה לו לומר לתפארת שהוא יותר מאומר לכבוד:
@43 **והלבשת אותם וגו' ומשחת וגו'**. פירוש אחר שילבישם בעוד הבגדים עליהם ימשחם ולא קודם ובזה הגיעתם הכהונה לידם, והוא אומרו **ומלאת את ידם**, ואולי כי יכוין באומרו **את ידם** בזה לומר כי באמצעות המעשה הם נשפעים בבחינת החסד המתיחסת ליד הגדולה והבן:
@43 **וקדשת**. פירוש במעשה הקרבנות כאומרו וזה אשר תעשה להם לקדש אותם. וטעם שהזכיר הדבר כאן לומר שלא יקדש אותם עד שיקדים לעשות הלבישה והמשיחה והבן:
@44 **ועשה להם מכנסי בד**. קשה למה איחר מצות המכנסים, ויש לומר לצד שאמר והלבשת אותם את אהרן לזה איחר המכנסים לומר שאינו חוזר עליו מצות והלבשת וגו'. ואין לומר שיכוין לומר שתהיה לבישתם באחרונה שהרי אמר הכתוב במקום אחר (ויקרא טז ד) ומכנסי בד יהיו על בשרו ודרשו ביומא (כ''ג:) שלא יהיה דבר קודם למכנסים אלא ודאי לטעם שכתבנו. עוד נראה שנתכוון לכותבו באחרונה ולהסמיך לו מצות והיו על אהרן וגו' ולא ישאו עון ומתו, ואם היה כוללו עם שאר בגדים ואומר והיו על אהרן וגו' תבא הסברא לומר כי לא באה האזהרה אלא על שאר בגדים אבל המכנסים אינם באים אלא כדי שלא תגלה ערוה ואין בהם צורך קדושת עבודה, לזה אמרם לבסוף וסמך להם האזהרה והעונש לומר כי מעכב הוא לקדושת הכהונה כשאר בגדים:
@46 **וזה הדבר אשר תעשה וגו'**. הכוונה להיות שקדם אליו מניעת המעשה כמו שפירשתי למעלה (כ''ז כ') שאין עליו אלא מצות הדבור לעושים, לזה **וזה הדבר** זה יצא מהכלל המושלל ויש לו לעשותו להקריב קרבנותיו ז' ימים, ואומרו **וזה** לצד שקדם וצוה שילבישנו לאהרן ולבניו וגמר אומר **וזה** גם כן תעשה, ואם לא אמר **אשר תעשה** אלא לקח פר וגו' יש מקום לומר כי יצוה לאהרן או לבניו לעשות, לזה אמר אשר תעשה כי הוא העושה. ולהיות שיש מקום לומר שלא הוכשר להקריב אלא קרבן שעה שהם קרבנות ימי המילואים של אהרן ובניו אבל קרבן שהוא קבוע לדורות שהם התמידים של כבש אחד בבקר וכבש אחד בין הערבים לא, לזה חזר ואמר **וזה אשר תעשה** וגו' **כבשים בני שנה שנים ליום תמיד**, ושלא יבין כי הותר במעשה הקרבנות תמיד, לזה אמר וזה לומר אין לו להקריב אלא ז' ימים האמורים בענין, ואומרו **הדבר** תתבאר למאן דאמר ביומא (ד':) מלואים כל הכתוב בהן מעכב, לזה אמר **וזה הדבר** כל הדבר האמור כאן לעיכוב, ולמאן דאמר דבר שאין מעכב לדורות אין מעכב במילואים אומרו **הדבר** לומר ולא כל דבר מעכב:
@46 **לקח פר וגו'**. אולי כי רשות נתונה להביא או משל אהרן ובניו או משל משה ואין עכבה בדבר:
@52 **ויצקת על ראשו ומשחת**. פירוש צריך יציקה על ראשו וצריך משיחה בפני עצמו וכמו כן לבניו כי הכתוב השוה אותם יחד דכתיב ומשחת אותם, וכמו כן בפרשת פקודי (לקמן מ' ט''ו) כתוב ומשחת אותם כאשר משחת את אביהם, וכן הוא מפורש בתורת כהנים (פ' צו):
@54 **ומלאת יד אהרן ויד בניו**. פירוש שימשח אהרן ובניו כמו שאמר למעלה ומשחת אותם ומלאת את ידם וכאן לא הזכיר המשיחה ורמזה באומרו ומלאת את ידם:
@55 **וסמך וגו'**. ולא אמר וסמכו שאהרן יסמוך בפני עצמו ואחר כך יסמכו בניו. שוב בא בידי תוספתא בפ''י דמנחות וזה לשונם ה' שהביאו זבח אחד כולן סומכין עליו לא כולן כאחד אלא כל אחד סומך ומסתלק עד כאן, ופסקו רמב''ם בפ''ג מהלכות מעשה הקרבנות, וכפ''ז אמר הכתוב **וסמך** לומר שיסמכו אחד אחד ולא יחד. אלא שצריך לדעת למה אמר ב' פעמים ולא הספיק בא' כמו שכתוב במעשה בפרשת צו (ויקרא ח' י''ח). ואולי כי מאחד הייתי אומר כי לצד שבו תלוי החטא שעליו בא הקרבן כי הוא עשה העגל ולא בניו לזה פרטו להקדימו לרמוז על הדבר ואין למדין ממנו לכל זבח, לזה כפל ואמר ב' פעמים **וסמך** לשון יחיד, ומעתה יש טעם נכון למה בפרשת צו בהודעת המעשה לא אמר לשון יחיד אלא בא', כי יספיק ללימוד שאנו צריכין לו, כי לא הוכפל במצוה אלא להסיר הטעות והבן:
@72 **מאשר לאהרן ומאשר וגו'**. צריך לדעת למה הוצרך לומר, ואולי שיכוין לומר שלא יאכל מכל חזה ושוק הניתנים לאהרן ולבניו זולת אלו:
@78 **ואכלו אותם אשר כופר**. פירוש לצד שהם בעליו ולא לצד שהם כהנים, והוא אומרו **אשר כופר בהם** כי אכילת שלמים לבעלים תפעיל הכפרה, ואפילו למשה אסורים הגם שאוכל החזה שאסור לאהרן:
@79 **כי קודש הוא**. פירוש ולזה ישרף:
@84 **את הכבש האחד וגו'**. אמר **את הכבש** כדי שלא תסתפק שהוא זולת ב' כבשים האמורים בסמוך, לזה אמר **את הכבש** פירוש אחד מהמוזכרים, ואומרו **האחד** נתכוון לומר שהגם שלא היה להם אלא כבש אחד בנמצא יקרבוהו בבוקר ואין כבש שני של בין הערבים מעכב, והנה אומרו **האחד** פירוש הגם שיש אחד ואין לו שני, ואפילו בחינוך שמעכב ראשון לב' כאומרם בפרק התכלת (מנחות פ''ד מ''ד), אין ב' מעכב לראשון:
@88 **ונועדתי שמה לבני ישראל ונקדש וגו'**. צריך לדעת כוונת הכתוב מה בא ללמדנו באומרו **ונועדתי שמה לבני ישראל**, ויראה כי בא לתת טעם למה שאומר בגמר דבריו **ונקדש בכבודי** ואמרו ז''ל (זבחים קט''ו:) שכאן נאמר למשה בקרובי אקדש, לזה הקדים לומר **ונועדתי שמה לבני ישראל** פירוש לצד שאני מזמן שכינתי לבני ישראל חוששני להם מפרצת גדר ומיעוט כבוד מהם לזה צריך לקדשו בקרובי כדי שייראו ממקדשי, ורמז לו שלא הוצרך עשות דבר אלא לצד ישראל אבל לצדו אינו צריך לאיום זה:
@91 **אני ה' אלהיהם**. טעם שכפל לומר כן פעם ב', אולי שנתכוון לרבות אפילו בזמן שאין שכינתו בתוכנו הוא ה' אלהינו ולו אנחנו. או ירצה על זה הדרך בידיעתם ובהכרתם הדבד כאומרו בתחלה וידעו וגו' בזה יהיו ראוים לקרוא שמי עליהם לומר ה' אלהיהם אבל זולת זה יפרקו עול ויהיו לאלהים אחרים ב''מ:
@92 **ועשית מזבח וגו'**. טעם שסידר כלי זה של פנים מאוחר מכל המשכן ועבודתו, כבר פירשתי בפרשת תרומה בפסוק (לעיל כ''ה ט') וכן תעשו, ואומרו **תעשה** למעט מעשה שעשה שלמה שלא היה עצי שטים שהיו כולו זהב:
@92 **חסלת פרשת תצוה**
